mapper.select:
SELECT s.*, u.real_name as studentName, u.student_no as studentNo
FROM score s
LEFT JOIN user u ON s.student_id = u.id
WHERE s.course_id = #{courseId}

    AND (u.real_name LIKE CONCAT('%', #{keyword}, '%') OR u.student_no LIKE CONCAT('%', #{keyword}, '%'))


    AND s.total_score >= #{minScore}


    AND s.total_score <= #{maxScore}

ORDER BY s.total_score DESC

mapper.update:
UPDATE score
usual_score = #{usualScore}, midterm_score = #{midtermScore}, final_score = #{finalScore}, total_score = #{totalScore}, grade_level = #{gradeLevel}, gpa = #{gpa},
WHERE id = #{id}
